"""Apply the recorded, frame-exact single-shot correction to the first cached export."""
from pathlib import Path
import json,subprocess,hashlib
B=Path('episodes/inventions-since-2000');d=json.loads((B/'delivery-patch.json').read_text());T=json.loads((B/'timeline.json').read_text());movie=Path('renders/inventions-since-2000/inventions-since-2000-v1.mp4');patch=Path(d['patchFile']);out=movie.with_name(movie.stem+'.corrected.mp4');backup=movie.with_name('authoring-hyperframes-v1.mp4');a=d['startFrame'];b=d['endFrameExclusive']
probe=json.loads(subprocess.check_output(['ffprobe','-v','error','-select_streams','v:0','-show_entries','stream=nb_frames','-of','json',str(patch)]));assert int(probe['streams'][0]['nb_frames'])==b-a,'Correction clip has wrong frame count'
if backup.exists():raise ValueError('This first-export patch was already applied. Use the normal render command for a new export.')
flt=f'[0:v]split=2[p0][p1];[p0]trim=end_frame={a},setpts=PTS-STARTPTS,format=yuv420p[before];[1:v]trim=end_frame={b-a},setpts=PTS-STARTPTS,scale=in_range=auto:out_range=tv:out_color_matrix=bt709,format=yuv420p[new];[p1]trim=start_frame={b},setpts=PTS-STARTPTS,format=yuv420p[after];[before][new][after]concat=n=3:v=1:a=0[v]'
subprocess.run(['ffmpeg','-v','error','-y','-i',str(movie),'-i',str(patch),'-i','public/episodes/inventions-since-2000/delivery-mix.wav','-filter_complex',flt,'-map','[v]','-map','2:a:0','-c:v','libx264','-preset','fast','-crf','17','-r','30','-pix_fmt','yuv420p','-color_range','tv','-colorspace','bt709','-color_trc','bt709','-color_primaries','bt709','-c:a','aac','-b:a','192k','-ar','48000','-t',str(T['duration']),'-movflags','+faststart',str(out)],check=True)
d['sourceRenderSha256']=hashlib.sha256(movie.read_bytes()).hexdigest();d['patchSha256']=hashlib.sha256(patch.read_bytes()).hexdigest();movie.replace(backup);out.replace(movie);d['applied']=True;d['method']='Frame trim/concat of only the corrected 192-frame shot, followed by a consistent H.264 encode and the local mastered audio. Future renders use corrected native HTML directly.';(B/'delivery-patch.json').write_text(json.dumps(d,indent=2)+'\n');print('Saved corrected delivery:',movie)
